async ({ git: { switchBranch }, shell: { execFile }, workspace: { read, edit } }) => {
  await switchBranch(["-c", "release-0.39.0"]);
  await execFile("npm", ["version", "0.39.0", "--no-git-tag-version"], { raise: true });
  const [c, r] = await Promise.all([read("CHANGELOG.md", { format: "raw" }), read("README.md", { format: "raw" })]);
  await Promise.all([
    edit("CHANGELOG.md", { revision: c.revision, changes: [{ kind: "replaceFile", content: c.content.replace("## [Unreleased]\n", "## [Unreleased]\n\n## [0.39.0] - 2026-11-18\n") }] }),
    edit("README.md", { revision: r.revision, changes: [{ kind: "replaceFile", content: r.content.replace("git:github.com/cv/pit@v0.38.1", "git:github.com/cv/pit@v0.39.0") }] }),
  ]);
  const d = await execFile("git", ["diff", "--stat"]);
  return d.stdout;
}
